/** Languages written right to left. The <html dir> and the whole mirrored layout come from
 * this one list; the CSS was already converted to logical properties so nothing else changes. */
export const RTL_LANGS: Lang[] = ['ar'];
export const dirFor = (lang: Lang) => (RTL_LANGS.includes(lang) ? 'rtl' : 'ltr');

export function t(lang: Lang) { return strings[lang]; }
export function langPrefix(lang: Lang) { return lang === 'en' ? '' : `/${lang}`; }
export const LANGS: Lang[] = ['en', 'es', 'fr', 'de', 'ru', 'ar', 'pt', 'hi'];

/** Each language named in itself — what a reader looking for their own language scans for. */
export const LANG_NAMES: Record<Lang, string> = { en: 'English', es: 'Español', fr: 'Français', de: 'Deutsch', ru: 'Русский', ar: 'العربية', pt: 'Português', hi: 'हिन्दी' };
